Write pytest tests for a hamming distance function comparing two equal-length DNA strings.

def hamming_distance(a, b):
    if len(a) != len(b):
        raise ValueError('lengths must match')
    return sum(x != y for x, y in zip(a, b))

output:
import pytest
from dna import hamming_distance

def test_distance_all_different():
    assert hamming_distance('AAAA', 'TTTT') == 4

def test_distance_partial():
    assert hamming_distance('GATTACA', 'GCTTACA') == 1

def test_distance_identical():
    assert hamming_distance('abc', 'abc') == 0

def test_distance_length_mismatch():
    with pytest.raises(ValueError):
        hamming_distance('a', 'ab')

